echo "remaining markers in target scope:"; grep -rln "<!-- rule-api\|<!-- rule-catalog\|<!-- spec-api:file" memory-api memory-viewers viewer-api .spec --include="*.md" 2>/dev/null | grep -v "/tree/"
echo "---git status (root)---"; git status --porcelain | head -20
echo "---git status memory-api---"; (cd memory-api && git status --porcelain | head -20)
echo "---git status memory-viewers---"; (cd memory-viewers && git status --porcelain | head -20)
echo "---git status viewer-api---"; (cd viewer-api && git status --porcelain | head -20)
echo "---check triple blank lines introduced---"
for f in memory-api/README.md memory-api/AGENTS.md memory-viewers/README.md viewer-api/README.md; do
  echo "== $f =="; grep -n -A0 -B0 -Pzo '\n\n\n' "$f" | wc -l
done

for p in . memory-api memory-viewers viewer-api context-stack; do
  echo "REPO:$p";
  if [ "$p" = "." ]; then
    dir=".";
  else
    dir="$p";
  fi;
  if [ -d "$dir" ]; then
    git -C "$dir" status --porcelain | awk '
    BEGIN{st=0;del=0;mod=0;un=0}
    /^\?\?/{un++; next}
    {idx=substr($0,1,1);wt=substr($0,2,1);
     if(idx!=" " && idx!="?") st++;
     if(idx=="D" || wt=="D") del++;
     if(idx=="M" || wt=="M") mod++;
    }
    END{print st " staged, " del " deleted, " mod " modified, " un " untracked"}
    '
  else
    echo "missing"
  fi
done
